seeded.js.src:
// A tiny seeded generator (mulberry32): same seed, same "random" numbers.
function seeded(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const roll = seeded(23);
const dice = [];
for (let i = 0; i < 6; i++) {
  dice.push(Math.floor(roll() * 6) + 1);
}
console.log(dice.join(" "));

