xray.js.src:
// The Professor's x-ray: show the 64 bits a number is stored in.
function xray(x) {
  const view = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, x);
  let bits = "";
  for (let i = 0; i < 8; i++) {
    bits += view.getUint8(i).toString(2).padStart(8, "0");
  }
  return bits;
}

for (const x of [1, 2, 3, -2, 0.5, 0.1]) {
  const b = xray(x);
  console.log(String(x).padEnd(4), b[0], b.slice(1, 12), b.slice(12));
}
